    buf.write(`${specDir}/b.yaml`, "b: 2");
    expect(buf.size).toBe(2);
    buf.discard();
    expect(buf.size).toBe(0);
    expect(buf.read(`${specDir}/a.yaml`)).toBeUndefined();
