// AC: @batch-write-buffer ac-2 — read-after-write within same batch
it("forward reference within batch sees previous command writes", () => {
  // This test already exists in batch-exec-engine.test.ts as "forward reference"
  // but this specifically verifies read-after-write semantics via the buffer
  const result = kspecJson<BatchExecResult>(
    `batch --commands '[{"command":"module add","args":{"title":"Batch Test Module","slug":"buf-test-mod"}},{"command":"item add","args":{"title":"Buf Test Feature","type":"feature","parent":"@buf-test-mod"}}]'`,
    tempDir,
  );
  expect(result.success).toBe(true);
  expect(result.summary.succeeded).toBe(2);

  // Both should be visible after batch completes
  const item = kspec("item get @buf-test-feature", tempDir);
  expect(item.stdout).toContain("Buf Test Feature");
});

// AC: @batch-write-buffer ac-4 — rollback on failure leaves .kspec/ unchanged
it("atomic batch with failure leaves spec dir unchanged", async () => {
  const specDir = path.join(tempDir, ".kspec");
  const beforeContent = await fs.readFile(path.join(specDir, "project.inbox.yaml"), "utf-8");

  const result = kspecJson<BatchExecResult>(
    `batch --commands '[{"command":"inbox add","args":{"text":"ok item"}},{"command":"task get","args":{"ref":"@nonexistent-task-ref-xyz"}}]'`,
    tempDir,
    { expectFail: true },
  );
  // task get is read-only, will fail validation before execution
  expect(result.success).toBe(false);

  // inbox.yaml should be unchanged
  const afterContent = await fs.readFile(path.join(specDir, "project.inbox.yaml"), "utf-8");
  expect(afterContent).toBe(beforeContent);
});

// AC: @batch-write-buffer ac-6 — other processes see pre-batch state
it("spec dir on disk is unchanged during batch execution (buffer is process-local)", async () => {
  // This is verified by the fact that we use in-memory buffer:
